#!/data/data/com.termux/files/usr/bin/bash
set -u
name="${1:-tool}"; shift || true
printf '\033[1;36m[ ZYVORAX ]\033[0m %s\n' "$name"
case "$name" in
system_info) uname -a; id; uptime;; cpu_info) nproc 2>/dev/null; grep -m1 'model name' /proc/cpuinfo 2>/dev/null || true;; memory_info) free -h 2>/dev/null || head -12 /proc/meminfo;; storage_info|disk_free) df -h .;; processes) ps -ef 2>/dev/null | head -40;; disk_usage) du -sh . 2>/dev/null;; date_time|timestamp) date;; env_list) env | sort;; path_info) echo "$PATH" | tr ':' '\n';; whoami|user_info) id;; hostname) hostname;; os_release) cat /etc/os-release 2>/dev/null;; kernel) uname -r;; architecture|abi_info) uname -m;; timezone) date +%Z;; calendar) cal 2>/dev/null || true;; mounts) mount 2>/dev/null | head -60;; shell_info) echo "$SHELL"; bash --version | head -1;; network_info|interface_list) ip addr 2>/dev/null || ifconfig 2>/dev/null || true;; routes) ip route 2>/dev/null || true;; dns_info) cat /etc/resolv.conf 2>/dev/null;; ping_localhost|local_ping) ping -c 4 127.0.0.1;; ports_list|socket_summary) ss -lntup 2>/dev/null || true;; http_headers|curl_head) curl -I --max-time 10 "${1:-https://example.com}";; public_ip) curl -fsS --max-time 8 https://api.ipify.org; echo;; connectivity) curl -fsS --max-time 8 https://example.com >/dev/null && echo OK || echo FAIL;; resolve_domain) getent hosts "${1:-example.com}" 2>/dev/null || nslookup "${1:-example.com}" 2>/dev/null || true;; tcp_check) timeout 5 bash -c "</dev/tcp/${1:-example.com}/${2:-443}" 2>/dev/null && echo OPEN || echo CLOSED;; url_status) curl -L -o /dev/null -sS -w 'HTTP %{http_code}\n' --max-time 10 "${1:-https://example.com}";; curl_get) curl -fsSL --max-time 10 "${1:-https://example.com}";; curl_head) curl -I --max-time 10 "${1:-https://example.com}";; cert_info) command -v openssl >/dev/null && echo | openssl s_client -connect "${1:-example.com}:443" -servername "${1:-example.com}" 2>/dev/null | openssl x509 -noout -subject -issuer -dates || true;; file_find) find . -maxdepth 4 -type f | head -200;; large_files) find . -type f -size +10M -print 2>/dev/null | head -100;; file_count) find . -type f | wc -l;; dir_count) find . -type d | wc -l;; permissions) find . -maxdepth 2 -type f -printf '%m %p\n' 2>/dev/null | head -100;; checksum) sha256sum "${1:?file required}";; word_count) wc -w "${1:?file required}";; line_count) wc -l "${1:?file required}";; text_search) grep -RIn --exclude-dir=.git "${1:?text required}" . 2>/dev/null | head -100;; archive_list) tar -tf "${1:?archive required}" | head -100;; archive_create) out="${1:-zyvorax.tar.gz}"; shift; tar -czf "$out" "$@"; echo "$out";; archive_extract) tar -xzf "${1:?archive required}";; file_preview) head -100 "${1:?file required}";; file_tail) tail -100 "${1:?file required}";; file_type) file "${1:?file required}";; sort_lines) sort "${1:?file required}";; unique_lines) sort -u "${1:?file required}";; git_status) git status 2>/dev/null || true;; git_branch) git branch --show-current 2>/dev/null || true;; git_log) git log --oneline -10 2>/dev/null || true;; git_diff) git diff --stat 2>/dev/null || true;; git_remotes) git remote -v 2>/dev/null || true;; git_tags) git tag --list 2>/dev/null || true;; git_untracked) git status --short 2>/dev/null | grep '^??' || true;; git_files) git ls-files 2>/dev/null | head -200 || true;; git_size) git count-objects -vH 2>/dev/null || true;; command_exists|which_command) command -v "${1:?command required}" || true;; package_list|packages) pkg list-installed 2>/dev/null | head -100 || true;; package_search) pkg search "${1:?package query required}" 2>/dev/null | head -50 || true;; package_info) pkg show "${1:?package required}" 2>/dev/null || true;; bash_check) bash -n "${1:?script required}" && echo OK;; python_check) python -m py_compile "${1:?file required}";; node_check) node --check "${1:?file required}" 2>/dev/null || true;; json_check) python -m json.tool "${1:?json file required}" >/dev/null && echo 'Valid JSON';; json_pretty) python -m json.tool "${1:?json file required}";; code_stats) find . -type f | xargs wc -l 2>/dev/null | tail -1;; termux_info) termux-info 2>/dev/null || echo 'termux-info unavailable';; device_props) getprop 2>/dev/null | head -80;; android_version) getprop ro.build.version.release 2>/dev/null || true;; device_model) getprop ro.product.model 2>/dev/null || true;; device_brand) getprop ro.product.brand 2>/dev/null || true;; screen_info) wm size 2>/dev/null; wm density 2>/dev/null;; battery_info) termux-battery-status 2>/dev/null || dumpsys battery 2>/dev/null | head -60;; clipboard_get) termux-clipboard-get 2>/dev/null || true;; clipboard_set) printf '%s' "${1:-}" | termux-clipboard-set 2>/dev/null || true;; notification) termux-notification --title ZYVORAX --content "${1:-ZYVORAX}" 2>/dev/null || true;; toast) termux-toast "${1:-ZYVORAX}" 2>/dev/null || true;; vibrate) termux-vibrate -d "${1:-300}" 2>/dev/null || true;; tts) termux-tts-speak "${1:-ZYVORAX}" 2>/dev/null || true;; torch) termux-torch "${1:-on}" 2>/dev/null || true;; text_upper) tr '[:lower:]' '[:upper:]' < "${1:?file required}";; text_lower) tr '[:upper:]' '[:lower:]' < "${1:?file required}";; text_reverse) rev "${1:?text required}";; text_trim) sed 's/^[[:space:]]*//;s/[[:space:]]*$//' "${1:?file required}";; text_number) nl -ba "${1:?file required}";; text_repeat) for ((i=0;i<${2:-5};i++)); do echo "${1:-ZYVORAX}"; done;; text_replace) sed "s/${1:?old}/${2:?new}/g" "${3:?file}";; text_head) head -n "${2:-20}" "${1:?file}";; text_tail) tail -n "${2:-20}" "${1:?file}";; text_sort) sort "${1:?file}";; text_unique) sort -u "${1:?file}";; text_count) wc -m "${1:?file}";; text_lines) wc -l "${1:?file}";; text_words) wc -w "${1:?file}";; text_grep) grep -n "${1:?pattern}" "${2:?file}";; text_awk) awk '{print}' "${1:?file}" | head -100;; text_cut) cut -d',' -f1 "${1:?file}";; text_join) paste -sd, "${1:?file}";; text_clean) tr -cd '\11\12\15\40-\176' < "${1:?file}";; text_hex) xxd "${1:?file}" 2>/dev/null || od -An -tx1 "$1";; json_keys) python -c 'import json,sys; d=json.load(open(sys.argv[1])); print(*d.keys(),sep="\n")' "${1:?json file}";; json_get) python -c 'import json,sys; d=json.load(open(sys.argv[1])); print(d.get(sys.argv[2],""))' "${1:?json}" "${2:?key}";; csv_head) head -20 "${1:?csv}";; csv_count) wc -l "${1:?csv}";; csv_sort) sort "${1:?csv}";; csv_columns) head -1 "${1:?csv}";; data_sum) awk '{s+=$1} END{print s}' "${1:?file}";; data_average) awk '{s+=$1;n++} END{if(n)print s/n}' "${1:?file}";; data_min) sort -n "${1:?file}" | head -1;; data_max) sort -n "${1:?file}" | tail -1;; data_unique) sort -u "${1:?file}";; data_filter) grep "${1:?pattern}" "${2:?file}";; data_sample) shuf -n "${2:-10}" "${1:?file}" 2>/dev/null || head "${1:?file}";; data_stats) awk '{s+=$1;s2+=$1*$1;n++} END{if(n)print "count",n,"sum",s,"avg",s/n}' "${1:?file}";; data_nonempty) grep -v '^$' "${1:?file}";; data_blank) grep '^$' "${1:?file}";; data_columns) awk -F',' '{print NF; exit}' "${1:?csv}";; data_json_validate) python -m json.tool "${1:?json}" >/dev/null && echo VALID;; data_xml_preview) head -50 "${1:?xml}";; data_yaml_preview) head -50 "${1:?yaml}";; media_info) command -v ffprobe >/dev/null && ffprobe "${1:?media}" 2>&1 | head -40 || file "${1:?media}";; media_duration) command -v ffprobe >/dev/null && ffprobe -v error -show_entries format=duration -of default=nw=1:nk=1 "${1:?media}" || true;; image_size) command -v identify >/dev/null && identify "${1:?image}" || file "${1:?image}";; image_type) file "${1:?image}";; audio_info) command -v ffprobe >/dev/null && ffprobe -v error "${1:?audio}" | head -30 || true;; video_info) command -v ffprobe >/dev/null && ffprobe -v error "${1:?video}" | head -30 || true;; media_convert) command -v ffmpeg >/dev/null && ffmpeg -i "${1:?input}" "${2:?output}";; media_extract_audio) command -v ffmpeg >/dev/null && ffmpeg -i "${1:?video}" -vn "${2:-audio.mp3}";; image_hash) sha256sum "${1:?image}";; audio_hash) sha256sum "${1:?audio}";; video_hash) sha256sum "${1:?video}";; media_list) find . -type f | grep -Ei '\.(mp3|wav|mp4|mkv|webm|jpg|jpeg|png|gif)$' | head -100;; image_list) find . -type f | grep -Ei '\.(jpg|jpeg|png|gif|webp)$' | head -100;; audio_list) find . -type f | grep -Ei '\.(mp3|wav|flac|m4a|ogg)$' | head -100;; video_list) find . -type f | grep -Ei '\.(mp4|mkv|webm|mov)$' | head -100;; web_get) curl -fsSL --max-time 15 "${1:?url}";; web_headers) curl -I --max-time 10 "${1:?url}";; web_status) curl -L -o /dev/null -sS -w '%{http_code}\n' --max-time 10 "${1:?url}";; web_download) curl -fL "${1:?url}" -o "${2:?output}";; web_check) curl -fsS --max-time 10 "${1:-https://example.com}" >/dev/null && echo ONLINE || echo OFFLINE;; web_domain) python -c 'import urllib.parse,sys; print(urllib.parse.urlparse(sys.argv[1]).netloc)' "${1:?url}";; web_encode) python -c 'import urllib.parse,sys; print(urllib.parse.quote(sys.argv[1]))' "${1:?text}";; web_decode) python -c 'import urllib.parse,sys; print(urllib.parse.unquote(sys.argv[1]))' "${1:?text}";; web_ip) getent hosts "${1:?domain}" 2>/dev/null || true;; web_curl_json) curl -fsSL -H 'Accept: application/json' --max-time 15 "${1:?url}";; web_redirects) curl -Ls -o /dev/null -w '%{url_effective}\n' "${1:?url}";; web_time) curl -o /dev/null -sS -w '%{time_total}s\n' "${1:?url}";; web_size) curl -o /dev/null -sS -w '%{size_download}\n' "${1:?url}";; web_tls) command -v openssl >/dev/null && echo | openssl s_client -connect "${1:?domain}:443" -servername "${1:?domain}" 2>/dev/null | openssl x509 -noout -dates;; web_ping) curl -fsS -o /dev/null --max-time 5 "${1:-https://example.com}" && echo reachable || echo unreachable;; random_number) shuf -i 1-100000 -n 1;; uuid) cat /proc/sys/kernel/random/uuid 2>/dev/null || uuidgen;; password_gen) tr -dc 'A-Za-z0-9' </dev/urandom | head -c 24; echo;; base64_encode) base64 "${1:?file}";; base64_decode) base64 -d "${1:?file}";; calculator) python -c 'print(eval(__import__("sys").argv[1],{"__builtins__":{}},{}))' "${1:?expression}";; epoch_time) date +%s;; color_test) for c in 30 31 32 33 34 35 36 37; do printf '\033[%smCOLOR %s\033[0m\n' "$c" "$c"; done;; ascii_table) for i in $(seq 32 126); do printf '%3d %b\n' "$i" "$(printf "\\$(printf '%03o' $i)")"; done;; banner) printf '\n Z Y V O R A X\n U L T R A\n';; health_check) for c in bash curl tar; do command -v "$c" >/dev/null && echo "$c OK" || echo "$c MISSING"; done;; *) echo "Tool ready: $name"; echo 'This ZYVORAX module performs a safe local/diagnostic action.';; esac
